            if(kind=="shader"){input=surface(owner,size);inputDisplay=new TextureRect{Texture=previous.GetTexture(),Size=(Vector2)size,Material=new ShaderMaterial{Shader=owner.Get("_straight_shader").As<Shader>()}};input.AddChild(inputDisplay);previous=input;}var target=surface(owner,size);var display=new TextureRect{Texture=previous.GetTexture(),Size=(Vector2)size,MouseFilter=Control.MouseFilterEnum.Ignore};var shaderValue=Get(effect,"shader");var shader=shaderValue.VariantType==Variant.Type.Object?shaderValue.AsGodotObject() as Shader:null;var material=new ShaderMaterial{Shader=kind=="shader"&&shader!=null?shader:owner.Get(kind=="warp"?"_warp_shader":"_shader").As<Shader>()};display.Material=material;target.AddChild(display);stages.Add(new Settings{["viewport"]=target,["display"]=display,["material"]=material,["input_viewport"]=input==null?default(Variant):Variant.From(input),["input_display"]=inputDisplay==null?default(Variant):Variant.From(inputDisplay),["original"]=original==null?default(Variant):Variant.From(original)});previous=target;
        }
