        if(layer.Get("kind").AsString()=="group"){var content=new Node2D{Position=Vector2.One*Pad};source.AddChild(content);foreach(var child in _documents.children(Document(owner),layer.Get("id").AsString()))build_layer(owner,child.As<Resource>(),content);}else foreach(var child in _documents.children(Document(owner),layer.Get("id").AsString()))build_layer(owner,child.As<Resource>(),root);
    }
    public void update_live_paint(Node owner,Resource layer,Settings view)
    {
