                var template=_documents.live_material_for_id(document,region.Get("template_id").AsString());var material=template?.Get("material").As<Resource>();var coverage=region.Get("coverage").As<Texture2D>();display.Visible=template!=null&&template.Get("visible").AsBool()&&material!=null&&coverage!=null;if(!display.Visible)continue;display.Texture=coverage;var id=template!.Get("id");if(!signatures.ContainsKey(id))signatures[id]=live_material_signature(material!);long signature=GD.Hash(new GArray{signatures[id],region.Get("coverage"),region.Get("coordinates"),region.Get("coordinate_rect"),region.Get("mapping"),region.Get("opacity"),layer.Get("dimensions")});
